import pandas as pd
import numpy as np

train = pd.read_csv('train.csv')
test = pd.read_csv('test.csv')
feature_cols = [c for c in train.columns if c != 'target']
X = train[feature_cols].values.astype(np.float64)
y = train['target'].values
X_test = test[feature_cols].values.astype(np.float64)
y_test = test['target'].values

mu = X.mean(axis=0)
std = X.std(axis=0) + 1e-8
Xs = (X - mu) / std
Xt = (X_test - mu) / std
n, d = Xs.shape

# Random forest from scratch
np.random.seed(42)

def build_tree(X, y, max_depth=1, n_features=None):
    if n_features is None:
        n_features = int(np.sqrt(d))

    if max_depth == 0 or len(np.unique(y)) == 1:
        return ('leaf', int(np.round(y.mean())))

    feat_idx = np.random.choice(d, size=n_features, replace=False)
    best_gain = -np.inf
    best_split = None

    def gini(y):
        if len(y) == 0:
            return 0
        p = y.mean()
        return 1 - p**2 - (1-p)**2

    parent_gini = gini(y)

    for j in feat_idx:
        vals = np.sort(np.unique(X[:, j]))
        if len(vals) < 2:
            continue
        mids = (vals[:-1] + vals[1:]) / 2
        # Subsample thresholds if too many
        if len(mids) > 10:
            mids = np.random.choice(mids, 10, replace=False)
        for t in mids:
            left = y[X[:, j] <= t]
            right = y[X[:, j] > t]
            if len(left) < 2 or len(right) < 2:
                continue
            gain = parent_gini - (len(left) * gini(left) + len(right) * gini(right)) / len(y)
            if gain > best_gain:
                best_gain = gain
                best_split = (j, t)

    if best_split is None:
        return ('leaf', int(np.round(y.mean())))

    j, t = best_split
    left_mask = X[:, j] <= t
    left = build_tree(X[left_mask], y[left_mask], max_depth-1, n_features)
    right = build_tree(X[~left_mask], y[~left_mask], max_depth-1, n_features)
    return ('split', j, t, left, right)

def tree_predict(tree, x):
    if tree[0] == 'leaf':
        return tree[1]
    _, j, t, left, right = tree
    if x[j] <= t:
        return tree_predict(left, x)
    else:
        return tree_predict(right, x)

# Build random forest
for n_trees in [50, 100, 200, 500]:
    for max_depth in [1, 2, 3]:
        trees = []
        for _ in range(n_trees):
            # Bootstrap
            boot_idx = np.random.choice(n, size=n, replace=True)
            tree = build_tree(Xs[boot_idx], y[boot_idx], max_depth=max_depth)
            trees.append(tree)

        # Predict test
        test_preds = []
        for i in range(len(Xt)):
            votes = [tree_predict(t, Xt[i]) for t in trees]
            test_preds.append(int(np.round(np.mean(votes))))
        test_acc = (np.array(test_preds) == y_test).mean()

        # OOB estimate
        oob_preds = np.zeros(n)
        oob_counts = np.zeros(n)
        for t_idx in range(n_trees):
            boot_idx = np.random.choice(n, size=n, replace=True)
            oob_mask = np.ones(n, dtype=bool)
            oob_mask[boot_idx] = False
            for i in np.where(oob_mask)[0]:
                oob_preds[i] += tree_predict(trees[t_idx], Xs[i])
                oob_counts[i] += 1
        valid = oob_counts > 0
        oob_acc = ((oob_preds[valid] / oob_counts[valid] >= 0.5).astype(int) == y[valid]).mean() if valid.any() else 0

        if test_acc >= 0.55:
            print(f'RF n={n_trees} depth={max_depth}: oob={oob_acc:.3f} test={test_acc:.3f}')
"

